class Flow:
    def classify(self, n):
        if n < 0: return 'neg'
        elif n == 0: return 'zero'
        else: return 'pos'

    def noop(self): pass

    def run(self, l, a):
        for e in l: print(f'- {e}')

        i = 0
        while i < 3: i = i + 1
        print(f'while: {i}')

        if a: print('x')
        else: print('y')

        for e in l:
            if e > 2: print(f'gt2: {e}')

        if a: print('p1'); print('q1')
        else: print('p2'); print('q2')

        print(self.classify(-5))
        print(self.classify(0))
        print(self.classify(7))
        self.noop()
        print('done')
